def shortest_path(graph, source, target):
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    paths = {node: None for node in graph}
    processed = set()
    candidates = {node: distances[node] for node in graph}
    while candidates:
        current_node = min(candidates, key=candidates.get)
        if current_node == target:
            break
        processed.add(current_node)
        candidates.pop(current_node)
        for neighbor, weight in graph.get(current_node, []):
            if neighbor in processed:
                continue
            if distances[current_node] + weight < distances[neighbor]:
                distances[neighbor] = distances[current_node] + weight
                paths[neighbor] = current_node
                candidates[neighbor] = distances[neighbor]
    if distances[target] == float('inf'):
        return (float('inf'), None)
    else:
        result_path = []
        while target is not None:
            result_path.append(target)
            target = paths[target]
        return (distances[target], result_path[::-1])
