def shortest_path(graph, source, target):
    num_nodes = len(graph)
    distances = [[float('inf')] * num_nodes for _ in range(num_nodes)]
    paths = [[None] * num_nodes for _ in range(num_nodes)]
    for node in graph:
        distances[node][node] = 0
        for neighbor, weight in graph[node]:
            distances[node][neighbor] = weight
            paths[node][neighbor] = (node, neighbor)
    for k in range(num_nodes):
        for i in range(num_nodes):
            for j in range(num_nodes):
                if distances[i][k] + distances[k][j] < distances[i][j]:
                    distances[i][j] = distances[i][k] + distances[k][j]
                    paths[i][j] = (paths[i][k][0], paths[k][j][1])
    if distances[source][target] == float('inf'):
        return (float('inf'), None)
    path = []
    while target is not None:
        path.append(target)
        a, b = paths[source][target]
        target = b
    path.reverse()
    return (distances[source][target], path)
